    schemeCitation: "Marking points quoted from the SEC marking scheme, Economics 2014 Higher Level — © State Examinations Commission.",
    id: "econ-2014-hl-sb-q3-a-i", topicId: "economics-1-4", conceptId: "categories-of-ped",
    section: "B", questionRef: "2014 HL Section B Q3(a)(i)",
    questionText: "Define the categories of Price Elasticity of Demand (PED): elastic, inelastic and unit elastic.",
    tariffModel: {"kind":"fixed","notation":"3 x 5","answer":null,"ofParts":null,"perPart":null}, totalMarks: 15,
    rows: [
    { id: "r-elastic", kind: "point", verbatim: "Elastic demand — The percentage / proportionate change in the price of the good causes a greater than percentage / proportionate change in quantity demanded of the good.", marks: 5, contextNote: "Elastic demand, 5 marks.", openList: true },
    { id: "r-inelastic", kind: "point", verbatim: "Inelastic Demand — The percentage / proportionate change in price of the good causes a lesser percentage/proportionate change in the quantity demanded of the good.", marks: 5, contextNote: "Inelastic Demand, 5 marks.", openList: true },
    { id: "r-unitary", kind: "point", verbatim: "Unitary Elastic Demand — The percentage / proportionate change in the price of the good is equal to the percentage / proportionate change in the quantity demanded of the good.", marks: 5, contextNote: "Unitary Elastic Demand, 5 marks.", openList: true },
    ],
