    schemeCitation: "Marking points quoted from the SEC marking scheme, Economics 2014 Higher Level — © State Examinations Commission.",
    id: "econ-2014-hl-sb-q8-a", topicId: "economics-3-1", conceptId: "the-deficit-and-the-debt",
    section: "B", questionRef: "2014 HL Section B Q8(a)",
    questionText: "Explain the relationship between a government Budget Deficit and the National Debt.",
    tariffModel: {"kind":"fixed","notation":"10 + 10","answer":null,"ofParts":null,"perPart":null}, totalMarks: 20,
    rows: [
    { id: "r-deficit", kind: "point", verbatim: "A government budget deficit exists when total government expenditure exceeds total government revenue. A budget deficit is financed by increased government borrowing.", marks: 10, contextNote: "The budget deficit, 10 marks.", openList: true },
    { id: "r-debt", kind: "point", verbatim: "National debt is the total amount (cumulative) of government borrowing which is outstanding (due / owed). A budget deficit will result in an increased national debt in absolute terms and a higher cost of servicing the national debt.", marks: 10, contextNote: "The national debt and the relationship, 10 marks.", openList: true },
    ],
