    section: "B", questionRef: "2019 HL Section B Q3(a)(i)",
    questionText: "Explain the term Price Elasticity of Demand (PED).",
    tariffModel: {"kind":"fixed","notation":"5","answer":null,"ofParts":null,"perPart":null}, totalMarks: 5,
